         margin: 0;
         min-height: 100vh;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
           "Segoe UI", sans-serif;
         color: var(--text);
         background:
           radial-gradient(circle at top, rgba(37, 99, 235, 0.12), transparent 40%),
           linear-gradient(180deg, #f8fafc 0%, var(--bg) 100%);
       }

       .app {
         min-height: 100vh;
         display: grid;
         place-items: center;
         padding: 24px;
       }

       .card {
         width: min(100%, 920px);
         display: grid;
         grid-template-columns: minmax(0, 1.45fr) minmax(320px, 0.95fr);
         gap: 24px;
         padding: 24px;
         border: 1px solid var(--line);
         border-radius: 28px;
         background: var(--panel);
         backdrop-filter: blur(22px);
         box-shadow: var(--shadow);
       }

       .preview {
         border-radius: 22px;
         overflow: hidden;
         position: relative;
         min-height: 540px;
         background: #0f172a;
       }

       .preview img {
         width: 100%;
         height: 100%;
         object-fit: cover;
         display: block;
       }

       .badge {
         position: absolute;
         top: 18px;
         left: 18px;
         padding: 8px 12px;
         border-radius: 999px;
         background: rgba(15, 23, 42, 0.65);
         color: #fff;
         font-size: 0.875rem;
         font-weight: 600;
       }

       .meta {
         display: flex;
         flex-direction: column;
         justify-content: center;
         gap: 20px;
         padding: 10px 8px 10px 4px;
       }

       .eyebrow {
         color: var(--accent);
         text-transform: uppercase;
         letter-spacing: 0.16em;
         font-size: 0.78rem;
         font-weight: 700;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 4vw, 3.25rem);
         line-height: 1.05;
       }

       p {
         margin: 0;
         color: var(--muted);
         font-size: 1rem;
         line-height: 1.6;
       }

       .details {
         display: grid;
         grid-template-columns: repeat(2, minmax(0, 1fr));
         gap: 12px;
       }

       .detail {
         padding: 14px 16px;
         border: 1px solid var(--line);
         border-radius: 18px;
         background: rgba(255, 255, 255, 0.72);
       }

       .detail strong {
         display: block;
         margin-top: 5px;
         font-size: 0.98rem;
       }

       .actions {
         display: flex;
         gap: 12px;
         margin-top: 4px;
       }

       .button {
         appearance: none;
         border: 0;
         border-radius: 14px;
         padding: 14px 18px;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
         transition: transform 140ms ease, box-shadow 140ms ease, background 140ms ease;
       }

       .button:active {
         transform: translateY(1px);
       }

       .button.trigger {
         background: linear-gradient(180deg, #ef4444 0%, #dc2626 100%);
         color: #fff;
         box-shadow: 0 14px 30px rgba(220, 38, 38, 0.25);
       }

       .button.secondary {
         background: #eef2ff;
         color: #3730a3;
       }

       dialog {
         width: min(92vw, 460px);
         border: 0;
         padding: 0;
         border-radius: 24px;
         background: var(--panel-strong);
         color: var(--text);
         box-shadow: var(--shadow);
       }

       dialog::backdrop {
         background: rgba(15, 23, 42, 0.46);
         backdrop-filter: blur(6px);
       }

       .dialog-shell {
         padding: 24px;
       }

       .dialog-icon {
         width: 48px;
         height: 48px;
         border-radius: 16px;
         display: grid;
         place-items: center;
         background: var(--danger-soft);
         color: var(--danger);
         margin-bottom: 16px;
         font-size: 1.35rem;
         font-weight: 900;
       }

       .dialog-shell h2 {
         margin: 0 0 10px;
         font-size: 1.45rem;
       }

       .dialog-shell p {
         margin-bottom: 24px;
       }

       .dialog-actions {
         display: flex;
         justify-content: flex-end;
         gap: 12px;
       }

       .button.danger {
         background: var(--danger);
         color: #fff;
       }

       .button.ghost {
         background: #f8fafc;
         color: #344054;
         border: 1px solid var(--line);
       }

       @media (max-width: 860px) {
         .card {
           grid-template-columns: 1fr;
         }

         .preview {
           min-height: 360px;
         }

         .details {
           grid-template-columns: 1fr;
         }
       }

       @media (max-width: 560px) {
         .app {
           padding: 14px;
         }

         .card,
         .dialog-shell {
           padding: 18px;
         }

         .actions,
         .dialog-actions {
           flex-direction: column;
         }

         .button {
           width: 100%;
         }
       }
     </style>
   </head>
   <body>
     <div id="root"></div>

     <script>
       const imageData =
         'data:image/svg+xml;charset=UTF-8,' +
         encodeURIComponent(`
           <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 900">
             <defs>
               <linearGradient id="g1" x1="0" y1="0" x2="1" y2="1">
                 <stop offset="0%" stop-color="#1d4ed8"/>
                 <stop offset="50%" stop-color="#6366f1"/>
                 <stop offset="100%" stop-color="#22c55e"/>
               </linearGradient>
               <radialGradient id="g2" cx="35%" cy="30%" r="75%">
                 <stop offset="0%" stop-color="#fff" stop-opacity="0.32"/>
                 <stop offset="100%" stop-color="#fff" stop-opacity="0"/>
               </radialGradient>
             </defs>
             <rect width="1200" height="900" fill="url(#g1)"/>
             <circle cx="300" cy="250" r="220" fill="url(#g2)"/>
             <circle cx="930" cy="250" r="170" fill="#ffffff" fill-opacity="0.12"/>
             <path d="M0 620C150 540 290 520 420 590C560 666 712 706 860 662C984 625 1084 560 1200 520V900H0V620Z" fill="#0f172a" fill-opacity="0.32"/>
             <path d="M180 675L360 490L520 610L710 420L940 610L1020 540V900H180Z" fill="#ffffff" fill-opacity="0.22"/>
             <rect x="120" y="120" width="280" height="70" rx="35" fill="#ffffff" fill-opacity="0.18"/>
             <rect x="120" y="210" width="410" height="18" rx="9" fill="#ffffff" fill-opacity="0.24"/>
             <rect x="120" y="244" width="300" height="18" rx="9" fill="#ffffff" fill-opacity="0.18"/>
           </svg>
         `);

       const App = () => `
         <main class="app">
           ${ImagePreviewPage()}
         </main>
       `;

       const ImagePreviewPage = () => `
         <section class="card" aria-label="Image preview">
           <div class="preview">
             <span class="badge">Library image</span>
             <img
               src="${imageData}"
               alt="Stylized abstract image preview"
             />
           </div>

           <div class="meta">
             <div>
               <div class="eyebrow">Preview</div>
               <h1>Delete this image from your library?</h1>
             </div>

             <p>
               This image is currently stored in your library. Use the delete button
               below if you want to remove it permanently.
             </p>

             <div class="details" aria-label="Image details">
               <div class="detail">
                 <span>File name</span>
                 <strong>sunset-landscape.jpg</strong>
               </div>
               <div class="detail">
                 <span>Resolution</span>
                 <strong>2400 × 1600</strong>
               </div>
             </div>

             <div class="actions">
               <button class="button secondary" type="button">Keep image</button>
               <button class="button trigger" type="button" id="open-dialog">
                 Delete image
               </button>
             </div>
           </div>
         </section>
       `;

       const DeleteDialog = () => `
         <dialog id="delete-dialog" aria-labelledby="delete-title">
           <div class="dialog-shell">
             <div class="dialog-icon" aria-hidden="true">!</div>
             <h2 id="delete-title">Delete this image?</h2>
             <p>
               This action will permanently remove <strong>sunset-landscape.jpg</strong>
               from your library. You won&apos;t be able to restore it later.
             </p>
             <div class="dialog-actions">
               <button class="button ghost" type="button" data-close-dialog>Cancel</button>
               <button class="button danger" type="button">Delete image</button>
             </div>
           </div>
         </dialog>
       `;

       const root = document.getElementById("root");
       root.innerHTML = App() + DeleteDialog();

       const dialog = document.getElementById("delete-dialog");
       const openDialog = document.getElementById("open-dialog");

       openDialog.addEventListener("click", () => {
         dialog.showModal();
       });

       dialog.addEventListener("click", (event) => {
         const rect = dialog.getBoundingClientRect();
         const clickedInDialog =
           rect.top <= event.clientY &&
           event.clientY <= rect.top + rect.height &&
           rect.left <= event.clientX &&
           event.clientX <= rect.left + rect.width;

         if (!clickedInDialog) {
           dialog.close();
         }
       });

       dialog.querySelector("[data-close-dialog]").addEventListener("click", () => {
         dialog.close();
       });
     </script>
   </body>
 </html>

')
